@mock_s3
def t2():
    c = boto3.client('s3', region_name='us-east-1')
    c.create_bucket(Bucket='b')
    print("t2 OK: nested mocks")

# 3. Moto inner, responses outer; requests to an AWS-served URL go through moto's responses_mock
@responses.activate
@mock_s3
def t3():
    # instance metadata is served via responses_mock (requests-based)
    r = requests.get("http://169.254.169.254/latest/meta-data/instance-id/")
    assert r.status_code == 200, r.status_code
    print("t3 OK: instance metadata via moto:", r.text[:20])

